define({"topics":[{"title":"Electrical Safety","shortdesc":"<p class=\"shortdesc\">You must follow all recommended safety procedures when servicing and working near energy sources.<\/p>","href":"r_ElectricalSafety_17.html","attributes":{"data-id":"id_2001693"},"menu":{"hasChildren":false},"tocID":"id_2001693-d46e86523","topics":[]},{"title":"Shutting down the host computer","shortdesc":"<p class=\"shortdesc\">Shutting down the host computer shuts down the system safely and turns off the power to the host computer.<\/p>","href":"t_ShuttingDownHostComputer_13.html","attributes":{"data-id":"id_2001469"},"menu":{"hasChildren":false},"tocID":"id_2001469-d46e86627","topics":[]},{"title":"Applying LOTO - ISC","shortdesc":"<p class=\"shortdesc\">Apply LOTO to both the gradient and system Power Distribution Unit (PDU) breakers on the MDP when servicing either of these items in the ISC. Apply LOTO to make sure of a safe environment when working on these parts.<\/p>","href":"t_Applying-LOTO-ISC_11.html","attributes":{"data-id":"id_2001781"},"menu":{"hasChildren":false},"tocID":"id_2001781-d46e86731","topics":[]},{"title":"Cleaning the CPC Multi-Nuclear Spectroscopy (MNS) cabinet filters","shortdesc":"<p class=\"shortdesc\">The CPC Multi-Nuclear Spectroscopy (MNS) cabinet has filters on the top of the unit, inside the front door, inside the rear door, and on the fans at the rear of the cabinet. This procedure shows how to inspect and clean these filters.<\/p>","href":"t_CleaningTheCPCMNSCabinetFilters.html","attributes":{"data-id":"id_2022569"},"menu":{"hasChildren":false},"tocID":"id_2022569-d46e86835","topics":[]},{"title":"Removing LOTO - ISC","shortdesc":"<p class=\"shortdesc\">Remove LOTO from the gradient and system PDU breakers on the MDP before restoring power to the ISC.<\/p>","href":"t_Removing-LOTO-ISC_13.html","attributes":{"data-id":"id_2001783"},"menu":{"hasChildren":false},"tocID":"id_2001783-d46e86939","topics":[]},{"title":"Starting up the host computer","shortdesc":"<p class=\"shortdesc\">How to start the host computer.<\/p>","href":"t_StartingUpTheHostComputer_13.html","attributes":{"data-id":"id_2001468"},"menu":{"hasChildren":false},"tocID":"id_2001468-d46e87043","topics":[]},{"title":"Doing a check scan","shortdesc":"<p class=\"shortdesc\"> A check scan is done at the conclusion of many procedures. This functional check assures the unit is in good clinical working order.<\/p>","href":"t_DoingACheckScan_22.html","attributes":{"data-id":"id_2001754"},"menu":{"hasChildren":false},"tocID":"id_2001754-d46e87147","topics":[]}]});